import json,subprocess
from pathlib import Path
root=Path('/tmp/engine-next-20261104')
reference=root/'reference'
common=['taskset','-c','2','npm','run','perf:engine','--','--mode=compile',f'--reference={reference}/scripts/lib/native_motion/engine.wasm',f'--reference-root={reference}','--confirm-rounds=24','--warmup=5','--reps=3','--margin-pct=2']
def measure(name,cell,*flags):
 subprocess.run(common+[f'--cells={cell}',f'--out={root}/{name}',*flags],cwd='/home/holo/line',check=True)
 return json.loads((root/name/'result.json').read_text())
def resources_pass(result):
 for case in result['resources']:
  a,b=[arm['resources'] for arm in case['arms']]
  if b['wasmLinearMemoryBytes']>1.05*a['wasmLinearMemoryBytes'] or b['processMaxRssBytes']>1.15*a['processMaxRssBytes']:return False
 return True
screen=measure('screen',61,'--rounds=12','--seed=1729')
if screen['decision']['verdict']=='FASTER' and resources_pass(screen):
 guard=measure('large-guard',62,'--rounds=12','--seed=1729')
 if guard['decision']['intervalPct'][1]<=2 and resources_pass(guard):
  confirm=measure('confirm',61,'--stage=confirm','--rounds=24','--seed=2718',f'--screen={root}/screen/result.json')
