  let totalFrames = 0;
  let speedSumPx = 0;
  let speedFrames = 0;
  let dyTotal = 0;

  for (let f = a; f <= b; f++) {
    if (airborneAt(det, f)) airFrames++;
    totalFrames++;

    const speed = speedAt(det, f);
    if (speed !== undefined) {
      speedSumPx += speed;
      speedFrames++;
    }

