  if (v0 === undefined) return null;
  const v0SpeedPx = hypot2(v0.x, v0.y);
  if (!Number.isFinite(v0SpeedPx)) return null;
  return {
    startFrame,
    prefixEndFrame: prefixEnd,
    airFrames,
    speedSumPx,
    speedFrames,
    dy,
    v0SpeedPx,
  };
}

