};

/** Counters and telemetry accumulated by every stage of one compilation. */
export function createSearchWork() {
  return {
    samples: 0,
    viableCandidates: 0,
    memoHits: 0,
    memoRejectedHits: 0,
    backtracks: 0,
    searchBudgetExhausted: false,
    observedConstructionRate: 0,
    refinementStats: null as any,
    terminalSelectionStats: null as any,
    budgetInterruptions: [] as BudgetInterruption[],
    planningDecisions: [] as any[],
    /** Sections whose request the search simplified at a dead end: [index, from, to]. */
    sectionFallbacks: [] as Array<[number, string, string]>,
    fragmentStats: {intervals: 0, probes: 0, replayFrames: 0},
    observedReceiverWork: {attempts: 0, viable: 0, physicsFrames: 0, failures: {} as Record<string, number>},
    opposingEntryWork: {attempts: 0, viable: 0, physicsFrames: 0, failures: {} as Record<string, number>},
    initialProposalWork: Object.fromEntries(['center', 'learned', 'memory', 'response', 'generic', 'compactFold']
      .map(k => [k, {attempts: 0, viable: 0, physicsFrames: 0}])),
    initializationRecovery: [] as Array<{index: number; frame: number; proposals: number; viable: number; physicalFrames: number}>,
  };
}

export type ArcSearchWork = ReturnType<typeof createSearchWork>;

/** Timeline, start state, engine lineage, memory and accounting for a
 * normalized spec. Targets are read exactly as authored; the search is
 * deterministic, and a seed reaches the compiler only through the plan. */
export function createArcCompileContext(spec: Spec, options: ArcMotionOptions): ArcCompileContext {
  function owned(memories = new Map<string, ArcControlMemory>()): ArcCompileContext {
    const data = buildContext(spec, options, memories);
    const context: ArcCompileContext = {...data,
      forkForStudy() {
        const copy = owned(new Map([...memories].map(([key, memory]) => [key, memory.fork()])));
        copy.work = structuredClone(context.work);
        for (const [key, memo] of data.lineage.memoContexts) copy.lineage.memoContexts.set(key, structuredClone(memo));
